actions.new_string:
def _decode_punycode(label: str) -> str:
    """Decode a Punycode label to Unicode.

    If the label starts with 'xn--' but is not valid Punycode,
    return the original label to maintain the invalid state rather than
    silently normalizing it.
    """
    lowered = label.lower()
    looks_like_puny = lowered.startswith("xn--")
    if looks_like_puny:
        try:
            return idna.decode(lowered)
        except (UnicodeError, IndexError):
            # Return original label for invalid Punycode
            return label
    return lowered
